/*
 * lru.c - LRU cache: chained hash table + intrusive doubly linked list.
 *
 * Entries live in a preallocated pool and refer to each other by 32-bit
 * index, which keeps nodes small and cache-friendly. Index 0 is a sentinel
 * that serves both as the list head and as the "none" marker for chains.
 */
#include "lru.h"

#include <stdlib.h>
#include <string.h>

#define NIL 0u

typedef struct {
    lru_slice key;
    lru_slice value;
    uint64_t hash;
    uint32_t prev;  /* towards most recently used */
    uint32_t next;  /* towards least recently used */
    uint32_t chain; /* next entry in the same bucket, or free-list link */
} lru_node;

struct lru_cache {
    lru_node *nodes;    /* nodes[0] is the list sentinel */
    uint32_t *buckets;  /* head index per bucket, NIL if empty */
    uint64_t mask;      /* bucket count - 1 (power of two) */
    unsigned shift;     /* 64 - log2(bucket count) */
    size_t capacity;    /* maximum number of live keys */
    size_t size;        /* current number of live keys */
    uint32_t pool_len;  /* nodes handed out so far (excluding sentinel) */
    uint32_t pool_cap;  /* nodes available (excluding sentinel) */
    uint32_t free_head; /* recycled nodes, linked through .chain */
};

static uint64_t hash_bytes(const char *p, uint32_t n)
{
    uint64_t h = 0xcbf29ce484222325ull ^ n;
    for (uint32_t i = 0; i < n; i++) {
        h ^= (unsigned char)p[i];
        h *= 0x100000001b3ull;
    }
    /* Finalizer (splitmix64) so the top bits are well mixed. */
    h ^= h >> 30;
    h *= 0xbf58476d1ce4e5b9ull;
    h ^= h >> 27;
    h *= 0x94d049bb133111ebull;
    h ^= h >> 31;
    return h;
}

static inline uint64_t bucket_of(const lru_cache *c, uint64_t hash)
{
    return (hash >> c->shift) & c->mask;
}

static inline bool slice_eq(lru_slice a, lru_slice b)
{
    return a.len == b.len && memcmp(a.ptr, b.ptr, a.len) == 0;
}

lru_cache *lru_create(size_t capacity, size_t max_entries)
{
    if (capacity == 0)
        return NULL;

    size_t live = capacity < max_entries ? capacity : max_entries;
    if (live == 0)
        live = 1;
    if (live >= UINT32_MAX - 1)
        return NULL;

    /* Load factor <= 0.5. */
    size_t nbuckets = 16;
    unsigned bits = 4;
    while (nbuckets < live * 2) {
        nbuckets <<= 1;
        bits++;
    }

    lru_cache *c = calloc(1, sizeof *c);
    if (!c)
        return NULL;
    c->nodes = malloc((live + 1) * sizeof *c->nodes);
    c->buckets = calloc(nbuckets, sizeof *c->buckets);
    if (!c->nodes || !c->buckets) {
        lru_destroy(c);
        return NULL;
    }

    c->mask = nbuckets - 1;
    c->shift = 64 - bits;
    c->capacity = capacity;
    c->pool_cap = (uint32_t)live;
    c->nodes[NIL].prev = NIL;
    c->nodes[NIL].next = NIL;
    return c;
}

void lru_destroy(lru_cache *c)
{
    if (!c)
        return;
    free(c->nodes);
    free(c->buckets);
    free(c);
}

size_t lru_size(const lru_cache *c)
{
    return c->size;
}

static inline void list_unlink(lru_cache *c, uint32_t i)
{
    lru_node *n = &c->nodes[i];
    c->nodes[n->prev].next = n->next;
    c->nodes[n->next].prev = n->prev;
}

static inline void list_push_front(lru_cache *c, uint32_t i)
{
    lru_node *head = &c->nodes[NIL];
    lru_node *n = &c->nodes[i];
    n->prev = NIL;
    n->next = head->next;
    c->nodes[head->next].prev = i;
    head->next = i;
}

/* Find the entry for `key`; if `link_out` is non-NULL it receives the address
 * of the link that points at the found entry (for unlinking). */
static uint32_t find(lru_cache *c, lru_slice key, uint64_t hash, uint32_t **link_out)
{
    uint32_t *link = &c->buckets[bucket_of(c, hash)];
    while (*link != NIL) {
        lru_node *n = &c->nodes[*link];
        if (n->hash == hash && slice_eq(n->key, key)) {
            if (link_out)
                *link_out = link;
            return *link;
        }
        link = &n->chain;
    }
    return NIL;
}

/* Remove entry `i` from its hash chain, the recency list, and return its
 * node to the free list. */
static void remove_node(lru_cache *c, uint32_t i)
{
    uint32_t *link = &c->buckets[bucket_of(c, c->nodes[i].hash)];
    while (*link != i)
        link = &c->nodes[*link].chain;
    *link = c->nodes[i].chain;

    list_unlink(c, i);
    c->nodes[i].chain = c->free_head;
    c->free_head = i;
    c->size--;
}

static uint32_t alloc_node(lru_cache *c)
{
    if (c->free_head != NIL) {
        uint32_t i = c->free_head;
        c->free_head = c->nodes[i].chain;
        return i;
    }
    if (c->pool_len < c->pool_cap)
        return ++c->pool_len;
    return NIL;
}

void lru_set(lru_cache *c, lru_slice key, lru_slice value)
{
    uint64_t hash = hash_bytes(key.ptr, key.len);
    uint32_t i = find(c, key, hash, NULL);
    if (i != NIL) {
        c->nodes[i].value = value;
        list_unlink(c, i);
        list_push_front(c, i);
        return;
    }

    /* Evicting before inserting is observably identical to inserting and
     * then evicting, and keeps the pool bounded by the capacity. */
    if (c->size >= c->capacity)
        remove_node(c, c->nodes[NIL].prev);

    i = alloc_node(c);
    if (i == NIL) {
        /* Pool exhausted: the caller underestimated max_entries. Fall back
         * to evicting the least recently used entry to make room. */
        remove_node(c, c->nodes[NIL].prev);
        i = alloc_node(c);
    }

    lru_node *n = &c->nodes[i];
    n->key = key;
    n->value = value;
    n->hash = hash;
    uint32_t *bucket = &c->buckets[bucket_of(c, hash)];
    n->chain = *bucket;
    *bucket = i;
    list_push_front(c, i);
    c->size++;
}

bool lru_get(lru_cache *c, lru_slice key, lru_slice *out)
{
    uint32_t i = find(c, key, hash_bytes(key.ptr, key.len), NULL);
    if (i == NIL)
        return false;
    *out = c->nodes[i].value;
    if (c->nodes[NIL].next != i) {
        list_unlink(c, i);
        list_push_front(c, i);
    }
    return true;
}

bool lru_del(lru_cache *c, lru_slice key)
{
    uint32_t *link;
    uint32_t i = find(c, key, hash_bytes(key.ptr, key.len), &link);
    if (i == NIL)
        return false;
    *link = c->nodes[i].chain;
    list_unlink(c, i);
    c->nodes[i].chain = c->free_head;
    c->free_head = i;
    c->size--;
    return true;
}

/*
 * lru.h - fixed-capacity LRU cache keyed by byte strings.
 *
 * The cache does not copy keys or values: callers pass slices whose storage
 * must outlive the cache (or at least the entry referring to them).
 * All operations run in O(1) expected time.
 */
#ifndef LRU_H
#define LRU_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

typedef struct {
    const char *ptr;
    uint32_t len;
} lru_slice;

typedef struct lru_cache lru_cache;

/*
 * Create a cache holding at most `capacity` keys. `max_entries` is an upper
 * bound on the number of keys that will ever be live at once (it may be
 * smaller than `capacity` when the caller knows the workload is short);
 * storage is preallocated for min(capacity, max_entries) entries.
 * Returns NULL on allocation failure or zero capacity.
 */
lru_cache *lru_create(size_t capacity, size_t max_entries);
void lru_destroy(lru_cache *cache);

/* Insert or overwrite; the key becomes most recently used. */
void lru_set(lru_cache *cache, lru_slice key, lru_slice value);

/* On hit, store the value in *out, mark the key most recent, return true. */
bool lru_get(lru_cache *cache, lru_slice key, lru_slice *out);

/* Remove the key; return true if it was present. */
bool lru_del(lru_cache *cache, lru_slice key);

size_t lru_size(const lru_cache *cache);

#endif /* LRU_H */

/*
 * main.c - LRU cache simulator driven by commands on standard input.
 *
 * The whole input is read into memory up front; the cache stores slices
 * into that buffer, so keys and values are never copied.
 */
#include "lru.h"

#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* ---------- input ---------- */

static char *read_all(FILE *f, size_t *len_out)
{
    size_t cap = 1 << 20, len = 0;
    char *buf = malloc(cap);
    if (!buf)
        return NULL;
    for (;;) {
        if (len == cap) {
            cap *= 2;
            char *grown = realloc(buf, cap);
            if (!grown) {
                free(buf);
                return NULL;
            }
            buf = grown;
        }
        size_t n = fread(buf + len, 1, cap - len, f);
        len += n;
        if (n == 0) {
            if (ferror(f)) {
                free(buf);
                return NULL;
            }
            break;
        }
    }
    *len_out = len;
    return buf;
}

typedef struct {
    const char *cur;
    const char *end;
} line_reader;

/* Return the next line (without '\n' or a trailing '\r'); false at EOF. */
static bool next_line(line_reader *r, lru_slice *line)
{
    if (r->cur >= r->end)
        return false;
    const char *start = r->cur;
    const char *nl = memchr(start, '\n', (size_t)(r->end - start));
    const char *stop = nl ? nl : r->end;
    r->cur = nl ? nl + 1 : r->end;
    if (stop > start && stop[-1] == '\r')
        stop--;
    line->ptr = start;
    line->len = (uint32_t)(stop - start);
    return true;
}

/* Split off the next space-delimited token; false if none remain. */
static bool next_token(lru_slice *rest, lru_slice *tok)
{
    const char *p = rest->ptr, *end = rest->ptr + rest->len;
    while (p < end && *p == ' ')
        p++;
    if (p == end)
        return false;
    const char *q = memchr(p, ' ', (size_t)(end - p));
    if (!q)
        q = end;
    tok->ptr = p;
    tok->len = (uint32_t)(q - p);
    rest->ptr = q;
    rest->len = (uint32_t)(end - q);
    return true;
}

static bool token_is(lru_slice tok, const char *word)
{
    size_t n = strlen(word);
    return tok.len == n && memcmp(tok.ptr, word, n) == 0;
}

static size_t count_lines(const char *buf, size_t len)
{
    size_t n = 1;
    for (const char *p = buf, *end = buf + len;
         (p = memchr(p, '\n', (size_t)(end - p))) != NULL; p++)
        n++;
    return n;
}

/* ---------- output ---------- */

typedef struct {
    char *buf;
    size_t len;
    size_t cap;
} out_buf;

static void out_flush(out_buf *o)
{
    if (o->len) {
        fwrite(o->buf, 1, o->len, stdout);
        o->len = 0;
    }
}

static void out_line(out_buf *o, const char *s, size_t n)
{
    if (o->len + n + 1 > o->cap)
        out_flush(o);
    memcpy(o->buf + o->len, s, n);
    o->len += n;
    o->buf[o->len++] = '\n';
}

static void out_uint(out_buf *o, size_t v)
{
    char tmp[24];
    size_t i = sizeof tmp;
    do {
        tmp[--i] = (char)('0' + v % 10);
        v /= 10;
    } while (v);
    out_line(o, tmp + i, sizeof tmp - i);
}

/* ---------- driver ---------- */

static bool parse_capacity(lru_slice line, size_t *out)
{
    lru_slice rest = line, tok;
    if (!next_token(&rest, &tok) || tok.len > 18)
        return false;
    size_t v = 0;
    for (uint32_t i = 0; i < tok.len; i++) {
        if (tok.ptr[i] < '0' || tok.ptr[i] > '9')
            return false;
        v = v * 10 + (size_t)(tok.ptr[i] - '0');
    }
    if (v == 0)
        return false;
    *out = v;
    return true;
}

static void run_command(lru_cache *cache, lru_slice line, out_buf *out)
{
    lru_slice rest = line, cmd, key, value;
    if (!next_token(&rest, &cmd))
        return; /* blank line */

    if (token_is(cmd, "GET")) {
        if (!next_token(&rest, &key))
            return;
        if (lru_get(cache, key, &value))
            out_line(out, value.ptr, value.len);
        else
            out_line(out, "NULL", 4);
    } else if (token_is(cmd, "SET")) {
        if (!next_token(&rest, &key) || !next_token(&rest, &value))
            return;
        lru_set(cache, key, value);
    } else if (token_is(cmd, "DEL")) {
        if (!next_token(&rest, &key))
            return;
        out_line(out, lru_del(cache, key) ? "1" : "0", 1);
    } else if (token_is(cmd, "SIZE")) {
        out_uint(out, lru_size(cache));
    }
    /* Unknown commands are ignored. */
}

int main(void)
{
    size_t len;
    char *input = read_all(stdin, &len);
    if (!input) {
        fprintf(stderr, "lru: failed to read input: %s\n", strerror(errno));
        return 1;
    }

    line_reader reader = { input, input + len };
    lru_slice line;
    size_t capacity;
    if (!next_line(&reader, &line) || !parse_capacity(line, &capacity)) {
        free(input);
        return 0; /* nothing to simulate */
    }

    lru_cache *cache = lru_create(capacity, count_lines(input, len));
    out_buf out = { malloc(1 << 16), 0, 1 << 16 };
    if (!cache || !out.buf) {
        fprintf(stderr, "lru: out of memory\n");
        lru_destroy(cache);
        free(out.buf);
        free(input);
        return 1;
    }

    while (next_line(&reader, &line))
        run_command(cache, line, &out);

    out_flush(&out);
    fflush(stdout);
    free(out.buf);
    lru_destroy(cache);
    free(input);
    return 0;
}
